package com.hospital.system.exception; import java.util.*; import org.springframework.dao.*; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; @RestControllerAdvice public class GlobalExceptionHandler { @ExceptionHandler(ApiException.class) ResponseEntity<Map<String,Object>> api(ApiException e){return body(e.getStatus(),e.getMessage());} @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<Map<String,Object>> valid(MethodArgumentNotValidException e){String m=e.getBindingResult().getFieldErrors().stream().findFirst().map(x->x.getField()+": "+x.getDefaultMessage()).orElse("Invalid input");return body(HttpStatus.BAD_REQUEST,m);} @ExceptionHandler(DataIntegrityViolationException.class) ResponseEntity<Map<String,Object>> data(DataIntegrityViolationException e){return body(HttpStatus.CONFLICT,"Database constraint conflict");} @ExceptionHandler(Exception.class) ResponseEntity<Map<String,Object>> other(Exception e){return body(HttpStatus.INTERNAL_SERVER_ERROR,"Unexpected server error");} private ResponseEntity<Map<String,Object>> body(HttpStatus s,String m){return ResponseEntity.status(s).body(Map.of("status",s.value(),"message",m));} }
